// Producer + Consumer with KafkaJS (Node.js)
import { Kafka } from 'kafkajs';

const kafka = new Kafka({ brokers: [process.env.KAFKA_BROKER] });

// --- PRODUCER ---
const producer = kafka.producer();
await producer.connect();

async function publishOrderPlaced(order) {
  await producer.send({
    topic: 'orders',
    messages: [{
      key: String(order.id),   // same key → same partition (ordering)
      value: JSON.stringify({
        eventType: 'order.placed',
        orderId: order.id,
        userId: order.userId,
        total: order.total,
        timestamp: Date.now(),
      }),
    }],
  });
  // Returns immediately — API response is not blocked by downstream
}

// --- CONSUMER (Notification Service) ---
const consumer = kafka.consumer({ groupId: 'notification-service' });
await consumer.connect();
await consumer.subscribe({ topic: 'orders', fromBeginning: false });

await consumer.run({
  eachMessage: async ({ message }) => {
    const event = JSON.parse(message.value.toString());
    if (event.eventType === 'order.placed') {
      await sendOrderConfirmationEmail(event.userId, event.orderId);
      // Kafka commits offset after eachMessage resolves (at-least-once)
    }
  },
});

// Queue vs Pub/Sub vs Kafka — when to use what

// Point-to-point Queue (BullMQ / SQS)
// - Each job consumed by exactly ONE worker
// - Best for: task queues — resize image, send email, process payment
// - Scaling: add more workers to increase throughput

// Pub/Sub (Redis Pub/Sub, SNS)
// - Each message delivered to ALL subscribers
// - Best for: fanout events, real-time notifications, cache invalidation broadcasts
// - Not durable — if subscriber is offline, messages are lost

// Kafka
// - Durable log — messages retained days/weeks after consumption
// - Multiple independent consumer groups, each with own offset
// - Best for: event sourcing, audit logs, data pipelines, high-throughput streams
// - Partition key determines ordering guarantee

// Delivery guarantees
const guarantees = {
  atMostOnce:    'fast, may lose messages — ok for metrics/logs',
  atLeastOnce:  'default for most queues, consumers must be idempotent',
  exactlyOnce:  'Kafka transactions, high cost — use only when required',
};

// Idempotency pattern for at-least-once consumers
async function processOrderIdempotent(orderId) {
  const processed = await redis.setnx(`processed:${orderId}`, 1);
  if (!processed) return; // already handled, skip duplicate
  await doActualWork(orderId);
}
